package com.sih.gap.controller; import com.sih.gap.dto.SmartQueueDtos.*; import com.sih.gap.service.*; import jakarta.validation.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/gap/queue") public class SmartQueueController{final SmartQueueService s;public SmartQueueController(SmartQueueService s){this.s=s;}@PostMapping("/check-in")@ResponseStatus(HttpStatus.CREATED)Ticket c(@Valid @RequestBody CheckInRequest r){return s.checkIn(r);}@GetMapping QueueView q(@RequestParam String serviceArea){return s.queue(serviceArea);}@PostMapping("/next") Ticket n(@RequestParam String serviceArea,@RequestParam String clinicianId){return s.callNext(serviceArea,clinicianId);}@GetMapping("/display")List<PublicTicket>d(@RequestParam String serviceArea){return s.display(serviceArea);}}